WITH dim_totals AS (SELECT p.city, src.status, COUNT(*) AS cnt, MIN(src.amount) AS min_amount, MAX(src.shipping_fee) AS max_shipping_fee, GROUPING_ID() AS gid FROM orders src JOIN customers p ON src.customer_id = p.id GROUP BY GROUPING SETS ((p.city, src.status), (p.city), ())) SELECT city, status, cnt, min_amount, max_shipping_fee, gid FROM dim_totals ORDER BY city ASC NULLS FIRST
